fn dense_dickson(p:&mut polynomial::Poly,n:u64)->Vec<u64>{let(mut a,mut b)=(vec![2],vec![0,1]);for _ in 0..n{let wb=p.mul(&[0,1],&b);let next=p.sub(&wb,&a);a=b;b=next;}a}
fn sf(p:&mut polynomial::Poly,q:&[u64],r:u64)->Vec<u64>{if q.len()==1{return q.to_vec()}let d:Vec<_>=(1..q.len()).map(|j|mul(j as u64,q[j],r)).collect();let g=p.gcd_monic(q,&d,2*q.len()).unwrap().polynomial;p.divrem(q,&g).unwrap().0}
fn phase_checks(){let(mut remainders,mut intersections,mut large,mut max_products,mut max_coeffs)=(0,0,0,0,0);
 for r in [7u64,19,97,281]{let mut p=polynomial::Poly::new(r).unwrap();for degree in [1usize,2,3,5]{for seed in 0..3{let mut q=vec![1];for j in 0..degree{q=p.mul(&q,&[(r-((j as u64+seed)%3))%r,1]);}
  for n in 0..=64{let dense=dense_dickson(&mut p,n);let want=p.divrem(&dense,&q).unwrap().1;let mut state=DicksonQuotient{p:polynomial::Poly::new(r).unwrap(),q:q.clone(),products:0,max_coefficients:0};assert_eq!(state.pair(n).unwrap().0,want);remainders+=1;}
  for l in 1..r.min(33){for epsilon in [1,r-1]{let got=implicit_phase(r,l,epsilon,&q,degree).unwrap();let mut dense=dense_dickson(&mut p,l);dense[0]=(dense[0]+r-mul(2,epsilon,r))%r;let squarefree=sf(&mut p,&q,r);let want=p.gcd_monic(&squarefree,&dense,2*r as usize).unwrap().polynomial;assert_eq!(got.0,want);assert!(got.1<=3*(64-l.leading_zeros())as usize);assert!(got.2<=2*degree+1);assert!(matches!(implicit_phase(r,l,epsilon,&q,degree-1),Err(Error::Limit)));intersections+=1;}}
 }}}
 let r=998244353u64;let mut p=polynomial::Poly::new(r).unwrap();let vs:Vec<_>=(1..=24).collect();let mut q=vec![1];for &v in &vs{let w=(v+pow(v,r-2,r))%r;q=p.mul(&q,&[(r-w)%r,1]);}
 for l in [71303168u64,499122176,998244352]{for epsilon in [1,r-1]{let(g,products,coeffs)=implicit_phase(r,l,epsilon,&q,24).unwrap();let mut want=vec![1];for &v in &vs{if pow(v,l,r)==epsilon{let w=(v+pow(v,r-2,r))%r;want=p.mul(&want,&[(r-w)%r,1]);}}assert_eq!(g,want);assert!(products<=3*(64-l.leading_zeros())as usize);assert!(coeffs<=49);max_products=max_products.max(products);max_coeffs=max_coeffs.max(coeffs);large+=1;}}
 assert_eq!(implicit_phase(19,3,1,&[1],0).unwrap().0,vec![1]);assert!(matches!(implicit_phase(19,0,1,&[1],0),Err(Error::Domain)));assert!(matches!(implicit_phase(19,3,0,&[1],0),Err(Error::Domain)));assert!(matches!(implicit_phase(19,3,1,&[0,2],1),Err(Error::Domain)));
 println!("dense_remainder_equalities={remainders} squarefree_intersection_equalities={intersections} large_exponent_controls={large} large_max_products={max_products} large_max_coefficients={max_coeffs} largest_exponent=998244352 supplied_constraint_degree=24 invalid_inputs=rejected");
}
